mapper.select:
select id from ai_service_case_action
where case_id=#{caseId} and actor_kind=#{actorKind} and actor_ref=#{actorRef}
  and idempotency_key=#{idempotencyKey}
limit 1

mapper.update:
update ai_service_case
set state=#{targetState}, state_version=state_version+1,

        customer_information_type=#{informationType}, customer_information=null,

    public_status=#{publicStatus}, last_public_message=#{publicMessage}, updated_at=now()
where case_id=#{caseId} and assignee_ref=#{processor}
  and state=#{expectedState} and state_version=#{expectedVersion}
